inputs.script:
let table = base.getTable("Emails");
let record = await table.selectRecordAsync(input.config().recordId);
let webhook = "https://hook.us1.make.com/REDACTED_PATH";

let payload = { recordId: record.id };
for (let field of table.fields) {
    payload[field.name] = record.getCellValue(field.name);
}

await fetch(webhook, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
});
